package main

import "github.com/goplus/lib/c"

// AllocaCStrs builds a stack-resident, null-terminated pointer array and copies
// every Go string into stack storage.

// CHECK: {{^}}@[[GLOB0:[0-9]+]] = private unnamed_addr constant [1 x i8] c"a", align 1{{$}}
// CHECK: {{^}}@[[GLOB1:[0-9]+]] = private unnamed_addr constant [1 x i8] c"b", align 1{{$}}
// CHECK: {{^}}@[[GLOB2:[0-9]+]] = private unnamed_addr constant [1 x i8] c"c", align 1{{$}}
// CHECK: {{^}}@[[GLOB3:[0-9]+]] = private unnamed_addr constant [4 x i8] c"%s\0A\00", align 1{{$}}

func main() {
	cstrs := c.AllocaCStrs([]string{"a", "b", "c"}, true)
	n := 0
	for {
		cstr := *c.Advance(cstrs, n)
		if cstr == nil {
			break
		}
		c.Printf(c.Str("%s\n"), cstr)
		n++
	}
}

